WHENEVER SQLERROR CONTINUE
ALTER SESSION SET TIME_ZONE='UTC';
ALTER SESSION SET NLS_DATE_FORMAT='YYYY-MM-DD HH24:MI:SS';
CREATE TABLE tc_edge_ora_num (id NUMBER(5) PRIMARY KEY, n_any NUMBER, n38 NUMBER(38,0), n3810 NUMBER(38,10), n_neg NUMBER(10,-3), n_p10_2 NUMBER(10,2), n_sgp NUMBER(5,7), n18 NUMBER(18,0), n19 NUMBER(19,0), n_int INTEGER, n_sm SMALLINT, n_fl FLOAT, n_fl10 FLOAT(10), n_dec DECIMAL(20,5), n_38_38 NUMBER(38,38), n_1 NUMBER(1));
COMMIT;
CREATE TABLE tc_edge_ora_bfl (id NUMBER(5) PRIMARY KEY, bf BINARY_FLOAT, bd BINARY_DOUBLE);
COMMIT;
CREATE TABLE tc_edge_ora_str (id NUMBER(5) PRIMARY KEY, c10 CHAR(10), c2000 CHAR(2000), v4000 VARCHAR2(4000), v10 VARCHAR2(10 CHAR), nc10 NCHAR(10), nv2000 NVARCHAR2(2000));
COMMIT;
CREATE TABLE tc_edge_ora_lob (id NUMBER(5) PRIMARY KEY, cl CLOB, ncl NCLOB, bl BLOB);
DECLARE b BLOB; h VARCHAR2(512); BEGIN FOR i IN 0..255 LOOP h := h || TO_CHAR(i,'FM0X'); END LOOP; INSERT INTO tc_edge_ora_lob(id,bl) VALUES (7, HEXTORAW(h)); END;
/
DECLARE c CLOB; BEGIN c := RPAD('z', 32767, 'z'); FOR i IN 1..130 LOOP c := c || RPAD('z', 32767, 'z'); END LOOP; INSERT INTO tc_edge_ora_lob(id,cl) VALUES (8, c); END;
/
COMMIT;
CREATE TABLE tc_edge_ora_raw (id NUMBER(5) PRIMARY KEY, r16 RAW(16), r2000 RAW(2000));
DECLARE h VARCHAR2(1024); BEGIN FOR i IN 0..255 LOOP h := h || TO_CHAR(i,'FM0X'); END LOOP; INSERT INTO tc_edge_ora_raw(id,r2000) VALUES (6, HEXTORAW(h)); END;
/
COMMIT;
CREATE TABLE tc_edge_ora_date (id NUMBER(5) PRIMARY KEY, d DATE);
COMMIT;
CREATE TABLE tc_edge_ora_ts (id NUMBER(5) PRIMARY KEY, t0 TIMESTAMP(0), t3 TIMESTAMP(3), t6 TIMESTAMP(6), t9 TIMESTAMP(9));
COMMIT;
CREATE TABLE tc_edge_ora_tz (id NUMBER(5) PRIMARY KEY, tz0 TIMESTAMP(0) WITH TIME ZONE, tz6 TIMESTAMP(6) WITH TIME ZONE, tz9 TIMESTAMP(9) WITH TIME ZONE, ltz0 TIMESTAMP(0) WITH LOCAL TIME ZONE, ltz6 TIMESTAMP(6) WITH LOCAL TIME ZONE, ltz9 TIMESTAMP(9) WITH LOCAL TIME ZONE);
COMMIT;
CREATE TABLE tc_edge_ora_intv (id NUMBER(5) PRIMARY KEY, iym INTERVAL YEAR(9) TO MONTH, iym2 INTERVAL YEAR(2) TO MONTH, ids INTERVAL DAY(9) TO SECOND(9), ids2 INTERVAL DAY(2) TO SECOND(0));
COMMIT;
CREATE TABLE tc_edge_ora_rid (id NUMBER(5) PRIMARY KEY, rid ROWID, urid UROWID(4000));
COMMIT;
CREATE TABLE tc_edge_ora_json (id NUMBER(5) PRIMARY KEY, j JSON);
COMMIT;
CREATE TABLE tc_edge_ora_xml (id NUMBER(5) PRIMARY KEY, x XMLTYPE);
COMMIT;
CREATE TABLE tc_edge_ora_bool (id NUMBER(5) PRIMARY KEY, b BOOLEAN);
COMMIT;
CREATE TABLE tc_edge_ora_vec (id NUMBER(5) PRIMARY KEY, v VECTOR(3, FLOAT32), v2 VECTOR(2, FLOAT64), v3 VECTOR(2, INT8));
COMMIT;
CREATE TABLE tc_edge_ora_long (id NUMBER(5) PRIMARY KEY, l LONG);
COMMIT;
CREATE TABLE tc_edge_ora_lraw (id NUMBER(5) PRIMARY KEY, l LONG RAW);
COMMIT;
SELECT table_name FROM user_tables WHERE table_name LIKE 'TC_EDGE_ORA%' ORDER BY 1;
